// Context: OS Loader applies adjustments based on Relocation Table

typedef struct {
    uintptr_t patch_offset; // Location within section to modify
    uint32_t symbol_index;  // Target address/symbol ID
    uint8_t reloc_type;     // e.g., R_X86_64_32
} RelocationEntry;

// OS assigned starting address for the program
uintptr_t ProgramLoadBase = 0x400000; 

// RVA (Relative Virtual Address) before loading
uintptr_t TargetFunctionRVA = 0x1A0; 

RelocationEntry entry = { .patch_offset = 0x24, .symbol_index = 5, .reloc_type = 1 };

// Adjustment calculation: Relative -> Absolute Address
uintptr_t FinalAbsoluteAddress = ProgramLoadBase + TargetFunctionRVA;

// Patching operation: Memory[ProgramLoadBase + entry.patch_offset] = FinalAbsoluteAddress;
